import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_op_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_maxpool_sum_scale_kernel(const float* input, float* output, int batch_size, int out_features, int kernel_size, float scale_factor, int num_windows) {
    int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const float* sample_input = input + batch_idx * out_features;

    extern __shared__ float shared_sums[];
    int tid = threadIdx.x;

    float thread_sum = 0.0f;
    for (int window_idx = tid; window_idx < num_windows; window_idx += blockDim.x) {
        int start = window_idx * kernel_size;
        int end = start + kernel_size;
        float max_val = -INFINITY;
        for (int i = start; i < end; ++i) {
            if (i >= out_features) break;
            float val = sample_input[i];
            max_val = fmaxf(max_val, val);
        }
        thread_sum += max_val;
    }

    shared_sums[tid] = thread_sum;
    __syncthreads();

    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (tid < s) {
            shared_sums[tid] += shared_sums[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        output[batch_idx] = shared_sums[0] * scale_factor;
    }
}

torch::Tensor fused_maxpool_sum_scale_cuda(torch::Tensor input, int kernel_size, float scale_factor) {
    int batch_size = input.size(0);
    int out_features = input.size(1);
    int num_windows = out_features / kernel_size;
    auto output = torch::zeros({batch_size}, input.options());

    const int block_size = 256;
    int grid_size = batch_size;

    size_t shared_mem_size = block_size * sizeof(float);

    fused_maxpool_sum_scale_kernel<<<grid_size, block_size, shared_mem_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        out_features,
        kernel_size,
        scale_factor,
        num_windows
    );

    return output;
}
"""

fused_op_cpp_source = "torch::Tensor fused_maxpool_sum_scale_cuda(torch::Tensor input, int kernel_size, float scale_factor);"

fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_op_cpp_source,
    cuda_sources=fused_op_source,
    functions=['fused_maxpool_sum_scale_cuda'],
    verbose=True,
    extra_cflags=['-O3'],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.kernel_size = kernel_size
        self.scale_factor = scale_factor
        self.fused_op = fused_op

    def forward(self, x):
        x = self.matmul(x)
        x = self.fused_op.fused_maxpool_sum_scale_cuda(x, self.kernel_size, self.scale_factor)
        return x
